// Regenerates src/Inkwright/Fonts/LatinGlyphData.cs and Standard14Data.cs.
//
// From the repository root:
//
//   dotnet run tools/gen-fontdata.cs -- <path to PDF32000_2008.md> <path to a directory of .afm files>
//
// The two inputs may instead be supplied through INKWRIGHT_PDF_SPEC and
// INKWRIGHT_AFM_DIRECTORY. The optional third argument is the output directory and defaults to
// the repository-relative src/Inkwright/Fonts.
//
// The encoding table comes from Annex D.2 of the specification and the metrics from the Adobe core
// font metrics, so the two generated files are derived from published data rather than transcribed
// by hand. Run this only when one of those sources changes.

using System.Globalization;
using System.Text;

string specPath = RequiredInput(args, 0, "INKWRIGHT_PDF_SPEC", "the ISO 32000 Markdown source");
string afmDirectory = RequiredInput(args, 1, "INKWRIGHT_AFM_DIRECTORY", "the Adobe AFM directory");
string outputDirectory = Path.GetFullPath(
    args.Length > 2 ? args[2] : Path.Combine("src", "Inkwright", "Fonts"));

if (!File.Exists(specPath))
    throw new FileNotFoundException($"The ISO 32000 source was not found at '{specPath}'.", specPath);
if (!Directory.Exists(afmDirectory))
    throw new DirectoryNotFoundException($"The Adobe AFM directory was not found at '{afmDirectory}'.");

Dictionary<string, int> specialUnicode = new(StringComparer.Ordinal)
{
    ["space"] = 0x20, ["bar"] = 0x7C, ["nbspace"] = 0xA0, ["sfthyphen"] = 0xAD,
};

Directory.CreateDirectory(outputDirectory);

static string RequiredInput(string[] arguments, int index, string environmentVariable, string description)
{
    string? value = arguments.Length > index ? arguments[index] : null;
    if (string.IsNullOrWhiteSpace(value))
        value = Environment.GetEnvironmentVariable(environmentVariable);

    if (string.IsNullOrWhiteSpace(value))
    {
        throw new ArgumentException(
            $"Supply {description} as argument {index + 1} or set {environmentVariable}. " +
            "Run this tool from the Inkwright repository root.");
    }

    return Path.GetFullPath(value);
}

// ---- Annex D.2: the Latin character set and its four encodings -------------------------------
string[] lines = File.ReadAllLines(specPath);
var latin = new List<(string Name, int Std, int Mac, int Win, int Pdf, string Char)>();

for (int i = 16457; i < 16600 && i < lines.Length; i++)
{
    string line = lines[i].Trim();
    if (!line.StartsWith('|'))
        continue;

    string[] cells = line.Split('|');
    for (int half = 0; half + 6 < cells.Length; half += 6)
    {
        string ch = Clean(cells[half + 1]);
        string name = Clean(cells[half + 2]);
        if (name.Length == 0 || name is "NAME" || !name.All(char.IsAsciiLetterOrDigit))
            continue;

        int std = Octal(cells[half + 3]);
        int mac = Octal(cells[half + 4]);
        int win = Octal(cells[half + 5]);
        int pdf = Octal(cells[half + 6]);
        if (std < 0 && mac < 0 && win < 0 && pdf < 0)
            continue;

        latin.Add((name, std, mac, win, pdf, ch));
    }
}

latin = [.. latin.DistinctBy(entry => entry.Name).OrderBy(entry => entry.Name, StringComparer.Ordinal)];
Console.WriteLine($"Latin glyphs parsed: {latin.Count}");

var builder = new StringBuilder();
builder.AppendLine("""
    // <auto-generated>
    // Built from ISO 32000-1 Annex D.2 by tools/gen-fontdata.cs. Do not edit by hand.
    // </auto-generated>

    namespace Inkwright.Fonts;

    /// <summary>
    /// The Adobe standard Latin character set of ISO 32000-1 Annex D.2: for every glyph name, its
    /// code in the four predefined encodings and the character it stands for.
    /// </summary>
    internal static class LatinGlyphData
    {
        /// <summary>One glyph per line: name, StandardEncoding, MacRomanEncoding, WinAnsiEncoding, PDFDocEncoding, code point. A dash means unencoded.</summary>
        internal const string Table =
    """);

foreach ((string name, int std, int mac, int win, int pdf, string ch) in latin)
{
    int code = ch.Length > 0 ? char.ConvertToUtf32(ch, 0) : -1;
    if (code < 0 && specialUnicode.TryGetValue(name, out int known))
        code = known;

    builder.Append("        \"");
    builder.Append(CultureInfo.InvariantCulture,
        $"{name} {Fmt(std)} {Fmt(mac)} {Fmt(win)} {Fmt(pdf)} {(code < 0 ? "-" : code.ToString("X4", CultureInfo.InvariantCulture))}");
    builder.AppendLine("\\n\" +");
}

builder.Length -= (" +" + Environment.NewLine).Length;
builder.AppendLine(";");
builder.AppendLine("}");
File.WriteAllText(Path.Combine(outputDirectory, "LatinGlyphData.cs"), builder.ToString());

// ---- Adobe core font metrics ------------------------------------------------------------------
string[] fonts =
[
    "Courier", "Courier-Bold", "Courier-BoldOblique", "Courier-Oblique",
    "Helvetica", "Helvetica-Bold", "Helvetica-BoldOblique", "Helvetica-Oblique",
    "Times-Roman", "Times-Bold", "Times-BoldItalic", "Times-Italic",
    "Symbol", "ZapfDingbats",
];

var metrics = new StringBuilder();
metrics.AppendLine("""
    // <auto-generated>
    // Built from the Adobe core font metrics by tools/gen-fontdata.cs. Do not edit by hand.
    // </auto-generated>

    namespace Inkwright.Fonts;

    /// <summary>
    /// Metrics for the fourteen fonts every conforming reader carries (ISO 32000-1 §9.6.2.2), so a
    /// document can use them without embedding anything.
    /// </summary>
    internal static class Standard14Data
    {
        /// <summary>One font per line: name, ascender, descender, cap height, italic angle, four bounding box values, then glyph name and width pairs.</summary>
        internal const string Table =
    """);

foreach (string font in fonts)
{
    string path = Path.Combine(afmDirectory, font + ".afm");
    if (!File.Exists(path))
    {
        Console.WriteLine($"missing {path}");
        continue;
    }

    int ascender = 0, descender = 0, capHeight = 0;
    double italic = 0;
    int[] box = [0, 0, 0, 0];
    var widths = new List<(string Name, int Width, int Code)>();

    foreach (string raw in File.ReadLines(path))
    {
        string line = raw.Trim();
        if (line.StartsWith("Ascender ", StringComparison.Ordinal))
            ascender = (int)double.Parse(line[9..], CultureInfo.InvariantCulture);
        else if (line.StartsWith("Descender ", StringComparison.Ordinal))
            descender = (int)double.Parse(line[10..], CultureInfo.InvariantCulture);
        else if (line.StartsWith("CapHeight ", StringComparison.Ordinal))
            capHeight = (int)double.Parse(line[10..], CultureInfo.InvariantCulture);
        else if (line.StartsWith("ItalicAngle ", StringComparison.Ordinal))
            italic = double.Parse(line[12..], CultureInfo.InvariantCulture);
        else if (line.StartsWith("FontBBox ", StringComparison.Ordinal))
            box = [.. line[9..].Split(' ', StringSplitOptions.RemoveEmptyEntries).Take(4)
                .Select(value => (int)double.Parse(value, CultureInfo.InvariantCulture))];
        else if (line.StartsWith("C ", StringComparison.Ordinal))
        {
            string[] parts = line.Split(';', StringSplitOptions.TrimEntries);
            int code = int.Parse(parts[0][2..], CultureInfo.InvariantCulture);
            int width = 0;
            string name = string.Empty;

            foreach (string part in parts)
            {
                if (part.StartsWith("WX ", StringComparison.Ordinal))
                    width = (int)double.Parse(part[3..], CultureInfo.InvariantCulture);
                else if (part.StartsWith("N ", StringComparison.Ordinal))
                    name = part[2..];
            }

            if (name.Length > 0)
                widths.Add((name, width, code));
        }
    }

    metrics.Append("        \"");
    metrics.Append(CultureInfo.InvariantCulture,
        $"{font} {ascender} {descender} {capHeight} {(int)italic} {box[0]} {box[1]} {box[2]} {box[3]}");

    foreach ((string name, int width, int code) in widths)
        metrics.Append(CultureInfo.InvariantCulture, $" {name} {width} {code}");

    metrics.AppendLine("\\n\" +");
    Console.WriteLine($"{font}: {widths.Count} glyphs");
}

metrics.Length -= (" +" + Environment.NewLine).Length;
metrics.AppendLine(";");
metrics.AppendLine("}");
File.WriteAllText(Path.Combine(outputDirectory, "Standard14Data.cs"), metrics.ToString());

Console.WriteLine("done");

static string Clean(string cell)
{
    string text = cell.Trim();
    int sup = text.IndexOf("<sup>", StringComparison.Ordinal);
    if (sup >= 0)
        text = text[..sup];

    return text.Trim();
}

static int Octal(string cell)
{
    string text = Clean(cell);
    return text.Length == 0 || !text.All(c => c is >= '0' and <= '7') ? -1 : Convert.ToInt32(text, 8);
}

static string Fmt(int value) => value < 0 ? "-" : value.ToString(CultureInfo.InvariantCulture);
